// Original shader by Yohei Nishitsuji (https://x.com/YoheiNishitsuji/status/1880399305196073072)
// Adapted for Shadertoy

// HSV to RGB color conversion
vec3 hsv(float h,float s,float v){
    vec4 t=vec4(1.,2.,1.,3.);
    vec3 p=abs(fract(vec3(h)+t.xzy)*6.-vec3(t.x));
    return v*mix(vec3(t.x),clamp(p-vec3(t.x),0.,1.),s);
}
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}
// Star Nest by Pablo Roman Andrioli
// License: MIT

#define iterations 17
#define formuparam 0.53

#define volsteps 20
#define stepsize 0.1

#define zoom   0.800
#define tile   0.850
#define speed  0.000 

#define brightness 0.0015
#define darkmatter 0.300
#define distfading 0.730
#define saturation 0.850


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 r = iResolution.xy;
    vec2 FC = fragCoord.xy;
    float t = iTime*0.005;
    vec4 o = vec4(0.1,0.1,0.1,0.0);
    float i,e,g,R,s;

 vec2 uv=fragCoord.xy/iResolution.xy-.5;
	uv.y*=iResolution.y/iResolution.x;
	vec3 dir=vec3(uv*zoom,1.);
	float time=iTime*speed+.25;

	//mouse rotation

	vec3 from=vec3(1.,.5,0.5);


	//volumetric rendering
	float s2=0.1,fade=1.;
	vec3 v=vec3(0.);
	for (int r=0; r<volsteps; r++) {
		vec3 p=from+s*dir*.5;
		p = abs(vec3(tile)-mod(p,vec3(tile*2.))); // tiling fold
		float pa,a=pa=0.;
		for (int i=0; i<iterations; i++) { 
			p=abs(p)/dot(p,p)-formuparam;
            p.xy*=rot(iTime*0.01);// the magic formula
			a+=abs(length(p)-pa); // absolute sum of average change
			pa=length(p);
		}
		float dm=max(0.,darkmatter-a*a*.001); //dark matter
		a*=a*a; // add contrast
		if (r>6) fade*=1.3-dm; // dark matter, don't render near
		//v+=vec3(dm,dm*.5,0.);
		v+=fade;
		v+=vec3(s2,s2*s2,s2*s2*s2*s2)*a*brightness*fade; // coloring based on distance
		fade*=distfading; // distance fading
		s+=stepsize;
	}
	v=mix(vec3(length(v)),v,saturation); //color adjust
	vec4 fc = vec4(v*.03,1.);	
    vec3 q,p,d=vec3(FC.xy/r-.5,1);


    for(q.zy--;i++<50.;){

        e+=i/20000.;


        o.rgb+=hsv(1.5,R+g*.12,e*i/50.);

        // Ray marching step size
        s=4.;

        // Advance the ray
        p=q+=d*e*R*.2;


        g+=p.x/s;
        g+=p.y+s;

        p=vec3((R=length(p))-1.5+(t)*.05,exp2(mod(-p.z,s)/R)-.2,p);
         p.xz*=rot(iTime*0.21); 

        for(e=--p.y;s<10000.;s+=s)

            e+=.01-abs(dot(sin(p.yxz*s),cos(p.xzz*s))/s*0.5);
          ;

    }

    o.rgb+=fc.xyz*vec3(0.1,0.2,1.)*2.;
    fragColor = o;
}
